import base from '@erakor/toolchain/oxfmt'

const config = {
  ...base,
  ignorePatterns: [
    // Generated by scripts/build-static.ts; formatting them would only add churn to the daily refresh.
    'src/data/*.generated.ts',
    // Recorded upstream feeds, kept byte-identical to what the providers served.
    'test/fixtures/',
    'pnpm-lock.yaml',
    // Prose is wrapped by hand.
    '*.md',
    // Generated by `pnpm build:openapi` (JSON.stringify layout).
    'public/openapi.json',
  ],
}

export default config
